// Package argparse is a small command-line argument parser.
//
// It supports boolean flags, flags with values, positional arguments and a
// help message generated from the definitions.
package argparse

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"text/tabwriter"
)

// ErrHelp is returned by Parse when -h or --help is given.
var ErrHelp = errors.New("help requested")

type flag struct {
	name, short, usage, def string
	isBool                  bool
	set                     func(string) error
}

type positional struct {
	name, usage string
}

// Parser holds the flag and argument definitions for one command.
type Parser struct {
	name, desc string
	flags      []*flag
	args       []positional
	argDst     []*string
	rest       *positional
	restDst    *[]string
}

// New returns a parser for the command name with a one-line description.
func New(name, desc string) *Parser {
	return &Parser{name: name, desc: desc}
}

// Bool defines a boolean flag. short may be empty.
func (p *Parser) Bool(name, short, usage string) *bool {
	v := new(bool)
	p.add(&flag{name: name, short: short, usage: usage, isBool: true, set: func(s string) error {
		b, err := strconv.ParseBool(s)
		*v = b
		return err
	}})
	return v
}

// String defines a flag that takes a string value. short may be empty.
func (p *Parser) String(name, short, def, usage string) *string {
	v := new(string)
	*v = def
	f := &flag{name: name, short: short, usage: usage, set: func(s string) error {
		*v = s
		return nil
	}}
	if def != "" {
		f.def = strconv.Quote(def)
	}
	p.add(f)
	return v
}

// Int defines a flag that takes an integer value. short may be empty.
func (p *Parser) Int(name, short string, def int, usage string) *int {
	v := new(int)
	*v = def
	f := &flag{name: name, short: short, usage: usage, set: func(s string) error {
		n, err := strconv.Atoi(s)
		if err == nil {
			*v = n
		}
		return err
	}}
	if def != 0 {
		f.def = strconv.Itoa(def)
	}
	p.add(f)
	return v
}

// Arg defines a required positional argument. Arguments are filled in the
// order they are defined.
func (p *Parser) Arg(name, usage string) *string {
	v := new(string)
	p.args = append(p.args, positional{name, usage})
	p.argDst = append(p.argDst, v)
	return v
}

// Rest collects every positional argument left after those defined with Arg.
// Without it, extra positional arguments are an error.
func (p *Parser) Rest(name, usage string) *[]string {
	if p.rest != nil {
		panic("argparse: Rest defined twice")
	}
	v := new([]string)
	p.rest = &positional{name, usage}
	p.restDst = v
	return v
}

func (p *Parser) add(f *flag) {
	if f.name == "" || strings.HasPrefix(f.name, "-") || strings.Contains(f.name, "=") {
		panic(fmt.Sprintf("argparse: invalid flag name %q", f.name))
	}
	if len(f.short) > 1 || f.short == "-" || f.short == "=" {
		panic(fmt.Sprintf("argparse: invalid short name %q for --%s", f.short, f.name))
	}
	if f.name == "help" || f.short == "h" {
		panic("argparse: --help and -h are reserved")
	}
	for _, g := range p.flags {
		if g.name == f.name || (f.short != "" && g.short == f.short) {
			panic(fmt.Sprintf("argparse: flag --%s redefined", f.name))
		}
	}
	p.flags = append(p.flags, f)
}

func (p *Parser) find(match func(*flag) bool) *flag {
	for _, f := range p.flags {
		if match(f) {
			return f
		}
	}
	return nil
}

// Parse parses args, which should not include the program name
// (pass os.Args[1:]). It returns ErrHelp if help was requested.
//
// Accepted forms: --name, --name=value, --name value, -n, -n value, -nvalue,
// -n=value and grouped short booleans such as -abc. A bare "--" ends flag
// parsing; a bare "-" is a positional argument.
func (p *Parser) Parse(args []string) error {
	var pos []string
	for i := 0; i < len(args); i++ {
		a := args[i]
		switch {
		case a == "--":
			pos = append(pos, args[i+1:]...)
			i = len(args)

		case strings.HasPrefix(a, "--"):
			name, val, hasVal := strings.Cut(a[2:], "=")
			if name == "help" {
				return ErrHelp
			}
			f := p.find(func(f *flag) bool { return f.name == name })
			if f == nil {
				return fmt.Errorf("unknown flag --%s", name)
			}
			if !hasVal {
				if f.isBool {
					val = "true"
				} else if i++; i < len(args) {
					val = args[i]
				} else {
					return fmt.Errorf("flag --%s needs a value", name)
				}
			}
			if f.set(val) != nil {
				return fmt.Errorf("invalid value %q for flag --%s", val, name)
			}

		case len(a) > 1 && a[0] == '-':
			for j := 1; j < len(a); j++ {
				c := a[j : j+1]
				if c == "h" {
					return ErrHelp
				}
				f := p.find(func(f *flag) bool { return f.short == c })
				if f == nil {
					return fmt.Errorf("unknown flag -%s", c)
				}
				if f.isBool {
					f.set("true")
					continue
				}
				// A value flag takes the remainder of the group, or the next argument.
				val := a[j+1:]
				if strings.HasPrefix(val, "=") {
					val = val[1:]
				} else if val == "" {
					if i++; i >= len(args) {
						return fmt.Errorf("flag -%s needs a value", c)
					}
					val = args[i]
				}
				if f.set(val) != nil {
					return fmt.Errorf("invalid value %q for flag -%s", val, c)
				}
				break
			}

		default:
			pos = append(pos, a)
		}
	}

	if len(pos) < len(p.args) {
		return fmt.Errorf("missing argument <%s>", p.args[len(pos)].name)
	}
	for i, dst := range p.argDst {
		*dst = pos[i]
	}
	extra := pos[len(p.args):]
	if p.rest == nil && len(extra) > 0 {
		return fmt.Errorf("unexpected argument %q", extra[0])
	}
	if p.rest != nil {
		*p.restDst = extra
	}
	return nil
}

// Usage returns the help message built from the definitions.
func (p *Parser) Usage() string {
	var b strings.Builder
	fmt.Fprintf(&b, "Usage: %s [options]", p.name)
	for _, a := range p.args {
		fmt.Fprintf(&b, " <%s>", a.name)
	}
	if p.rest != nil {
		fmt.Fprintf(&b, " [%s...]", p.rest.name)
	}
	b.WriteString("\n")
	if p.desc != "" {
		fmt.Fprintf(&b, "\n%s\n", p.desc)
	}

	w := tabwriter.NewWriter(&b, 0, 0, 2, ' ', 0)
	if len(p.args) > 0 || p.rest != nil {
		fmt.Fprintln(w, "\nArguments:")
		for _, a := range p.args {
			fmt.Fprintf(w, "  %s\t%s\n", a.name, a.usage)
		}
		if p.rest != nil {
			fmt.Fprintf(w, "  %s...\t%s\n", p.rest.name, p.rest.usage)
		}
		w.Flush()
	}

	fmt.Fprintln(w, "\nOptions:")
	for _, f := range p.flags {
		fmt.Fprintf(w, "  %s\t%s\n", flagLabel(f), flagUsage(f))
	}
	fmt.Fprintf(w, "  -h, --help\tshow this help\n")
	w.Flush()
	return b.String()
}

func flagLabel(f *flag) string {
	s := "    --" + f.name
	if f.short != "" {
		s = "-" + f.short + ", --" + f.name
	}
	if !f.isBool {
		s += " <value>"
	}
	return s
}

func flagUsage(f *flag) string {
	if f.def == "" {
		return f.usage
	}
	return fmt.Sprintf("%s (default %s)", f.usage, f.def)
}
