package main

import (
	"errors"
	"fmt"
	"os"

	"argparse"
)

func main() {
	p := argparse.New("copy", "Copy files into a directory.")
	verbose := p.Bool("verbose", "v", "print each file as it is copied")
	force := p.Bool("force", "f", "overwrite existing files")
	output := p.String("output", "o", ".", "destination directory")
	jobs := p.Int("jobs", "j", 1, "number of parallel workers")
	source := p.Arg("source", "first file to copy")
	files := p.Rest("files", "more files to copy")

	if err := p.Parse(os.Args[1:]); err != nil {
		if errors.Is(err, argparse.ErrHelp) {
			fmt.Print(p.Usage())
			return
		}
		fmt.Fprintf(os.Stderr, "error: %v\n\n%s", err, p.Usage())
		os.Exit(2)
	}

	fmt.Printf("verbose=%v force=%v output=%q jobs=%d source=%q files=%q\n",
		*verbose, *force, *output, *jobs, *source, *files)
}
