package argparse

import (
	"errors"
	"reflect"
	"strings"
	"testing"
)

type result struct {
	verbose, force *bool
	output         *string
	jobs           *int
	source         *string
	files          *[]string
}

func newParser() (*Parser, result) {
	p := New("copy", "Copy files into a directory.")
	return p, result{
		verbose: p.Bool("verbose", "v", "print each file"),
		force:   p.Bool("force", "f", "overwrite"),
		output:  p.String("output", "o", ".", "destination directory"),
		jobs:    p.Int("jobs", "j", 1, "parallel workers"),
		source:  p.Arg("source", "first file"),
		files:   p.Rest("files", "more files"),
	}
}

func TestParse(t *testing.T) {
	tests := []struct {
		args    string
		verbose bool
		force   bool
		output  string
		jobs    int
		source  string
		files   []string
	}{
		{"a", false, false, ".", 1, "a", nil},
		{"--verbose --output out --jobs 4 a b c", true, false, "out", 4, "a", []string{"b", "c"}},
		{"--output=out --jobs=4 --verbose=false a", false, false, "out", 4, "a", nil},
		{"-v -o out -j 4 a", true, false, "out", 4, "a", nil},
		{"-vf -oout -j=4 a", true, true, "out", 4, "a", nil},
		{"-vfo out a", true, true, "out", 1, "a", nil},
		{"a -v b --force c", true, true, ".", 1, "a", []string{"b", "c"}},
		{"-v -- -f --output", true, false, ".", 1, "-f", []string{"--output"}},
		{"- -j -2", false, false, ".", -2, "-", nil},
		{"--output= a", false, false, "", 1, "a", nil},
	}
	for _, tt := range tests {
		p, r := newParser()
		if err := p.Parse(strings.Fields(tt.args)); err != nil {
			t.Errorf("%q: unexpected error: %v", tt.args, err)
			continue
		}
		if *r.verbose != tt.verbose || *r.force != tt.force || *r.output != tt.output ||
			*r.jobs != tt.jobs || *r.source != tt.source ||
			!reflect.DeepEqual(append([]string(nil), *r.files...), tt.files) {
			t.Errorf("%q: got verbose=%v force=%v output=%q jobs=%d source=%q files=%q",
				tt.args, *r.verbose, *r.force, *r.output, *r.jobs, *r.source, *r.files)
		}
	}
}

func TestParseErrors(t *testing.T) {
	tests := []struct{ args, want string }{
		{"", "missing argument <source>"},
		{"--nope a", "unknown flag --nope"},
		{"-x a", "unknown flag -x"},
		{"a --output", "flag --output needs a value"},
		{"a -o", "flag -o needs a value"},
		{"a --jobs many", `invalid value "many" for flag --jobs`},
		{"a -j many", `invalid value "many" for flag -j`},
		{"a --verbose=maybe", `invalid value "maybe" for flag --verbose`},
	}
	for _, tt := range tests {
		p, _ := newParser()
		err := p.Parse(strings.Fields(tt.args))
		if err == nil || err.Error() != tt.want {
			t.Errorf("%q: got error %v, want %q", tt.args, err, tt.want)
		}
	}
}

func TestExtraArgument(t *testing.T) {
	p := New("one", "")
	p.Arg("file", "the file")
	if err := p.Parse([]string{"a", "b"}); err == nil || err.Error() != `unexpected argument "b"` {
		t.Errorf("got error %v", err)
	}
}

func TestHelp(t *testing.T) {
	for _, args := range []string{"-h", "--help", "a -vh"} {
		p, _ := newParser()
		if err := p.Parse(strings.Fields(args)); !errors.Is(err, ErrHelp) {
			t.Errorf("%q: got %v, want ErrHelp", args, err)
		}
	}
}

func TestUsage(t *testing.T) {
	p, _ := newParser()
	want := `Usage: copy [options] <source> [files...]

Copy files into a directory.

Arguments:
  source    first file
  files...  more files

Options:
  -v, --verbose         print each file
  -f, --force           overwrite
  -o, --output <value>  destination directory (default ".")
  -j, --jobs <value>    parallel workers (default 1)
  -h, --help            show this help
`
	if got := p.Usage(); got != want {
		t.Errorf("usage mismatch:\n%s", got)
	}
}
