// Package argparse is a small command-line argument parser.
//
// It supports boolean flags, flags with values, positional arguments and a
// help message generated from the definitions.
package argparse

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"text/tabwriter"
)

// ErrHelp is returned by Parse when -h or --help is given.
var ErrHelp = errors.New("help requested")

type flag struct {
	name, short, usage, def string
	isBool                  bool
	set                     func(string) error
}

type positional struct {
	name, usage string
}

// Parser holds the flag and argument definitions for one command.
type Parser struct {
	name, desc string
	flags      []*flag
	args       []positional
	argDst     []*string
	rest       *positional
	restDst    *[]string
}

// New returns a parser for the command name with a one-line description.
func New(name, desc string) *Parser {
	return &Parser{name: name, desc: desc}
}

// Bool defines a boolean flag. short may be empty.
func (p *Parser) Bool(name, short, usage string) *bool {
	v := new(bool)
	p.add(&flag{name: name, short: short, usage: usage, isBool: true, set: func(s string) error {
		b, err := strconv.ParseBool(s)
		if err == nil {
			*v = b
		}
		return err
	}})
	return v
}

// String defines a flag that takes a string value. short may be empty.
func (p *Parser) String(name, short, def, usage string) *string {
	v := new(string)
	*v = def
	f := &flag{name: name, short: short, usage: usage, set: func(s string) error {
		*v = s
		return nil
	}}
	if def != "" {
		f.def = strconv.Quote(def)
	}
	p.add(f)
	return v
}

// Int defines a flag that takes an integer value. short may be empty.
func (p *Parser) Int(name, short string, def int, usage string) *int {
	v := new(int)
	*v = def
	f := &flag{name: name, short: short, usage: usage, set: func(s string) error {
		n, err := strconv.Atoi(s)
		if err == nil {
			*v = n
		}
		return err
	}}
	if def != 0 {
		f.def = strconv.Itoa(def)
	}
	p.add(f)
	return v
}

// Arg defines a required positional argument. Arguments are filled in the
// order they are defined.
func (p *Parser) Arg(name, usage string) *string {
	v := new(string)
	p.args = append(p.args, positional{name, usage})
	p.argDst = append(p.argDst, v)
	return v
}

// Rest collects every positional argument left after those defined with Arg.
// Without it, extra positional arguments are an error.
func (p *Parser) Rest(name, usage string) *[]string {
	if p.rest != nil {
		panic("argparse: Rest defined twice")
	}
	v := new([]string)
	p.rest = &positional{name, usage}
	p.restDst = v
	return v
}

func (p *Parser) add(f *flag) {
	if f.name == "" || strings.HasPrefix(f.name, "-") || strings.Contains(f.name, "=") {
		panic(fmt.Sprintf("argparse: invalid flag name %q", f.name))
