		if g.name == f.name || (f.short != "" && g.short == f.short) {
			panic(fmt.Sprintf("argparse: flag --%s redefined", f.name))
		}
	}
	p.flags = append(p.flags, f)
}

func (p *Parser) find(match func(*flag) bool) *flag {
	for _, f := range p.flags {
		if match(f) {
			return f
		}
	}
	return nil
}

// Parse parses args, which should not include the program name
// (pass os.Args[1:]). It returns ErrHelp if help was requested.
//
// Accepted forms: --name, --name=value, --name value, -n, -n value, -nvalue,
// -n=value and grouped short booleans such as -abc. A bare "--" ends flag
// parsing; a bare "-" is a positional argument.
func (p *Parser) Parse(args []string) error {
	var pos []string
	for i := 0; i < len(args); i++ {
		a := args[i]
		switch {
		case a == "--":
			pos = append(pos, args[i+1:]...)
			i = len(args)

		case strings.HasPrefix(a, "--"):
			name, val, hasVal := strings.Cut(a[2:], "=")
			if name == "help" {
				return ErrHelp
			}
			f := p.find(func(f *flag) bool { return f.name == name })
			if f == nil {
				return fmt.Errorf("unknown flag --%s", name)
			}
			if !hasVal {
				if f.isBool {
					val = "true"
				} else if i++; i < len(args) {
					val = args[i]
				} else {
					return fmt.Errorf("flag --%s needs a value", name)
				}
			}
			if f.set(val) != nil {
				return fmt.Errorf("invalid value %q for flag --%s", val, name)
			}

		case len(a) > 1 && a[0] == '-':
			for j := 1; j < len(a); j++ {
				c := a[j : j+1]
				if c == "h" {
					return ErrHelp
				}
				f := p.find(func(f *flag) bool { return f.short == c })
				if f == nil {
					return fmt.Errorf("unknown flag -%s", c)
				}
				if f.isBool {
					f.set("true")
					continue
				}
				// A value flag takes the remainder of the group, or the next argument.
				val := a[j+1:]
				if strings.HasPrefix(val, "=") {
					val = val[1:]
				} else if val == "" {
					if i++; i >= len(args) {
						return fmt.Errorf("flag -%s needs a value", c)
					}
					val = args[i]
				}
				if f.set(val) != nil {
					return fmt.Errorf("invalid value %q for flag -%s", val, c)
				}
				break
			}

		default:
			pos = append(pos, a)
		}
	}

	if len(pos) < len(p.args) {
		return fmt.Errorf("missing argument <%s>", p.args[len(pos)].name)
	}
	for i, dst := range p.argDst {
		*dst = pos[i]
	}
	extra := pos[len(p.args):]
	if p.rest == nil && len(extra) > 0 {
		return fmt.Errorf("unexpected argument %q", extra[0])
	}
	if p.rest != nil {
		*p.restDst = extra
	}
	return nil
}

// Usage returns the help message built from the definitions.
func (p *Parser) Usage() string {
	var b strings.Builder
	fmt.Fprintf(&b, "Usage: %s [options]", p.name)
	for _, a := range p.args {
		fmt.Fprintf(&b, " <%s>", a.name)
	}
	if p.rest != nil {
		fmt.Fprintf(&b, " [%s...]", p.rest.name)
	}
	b.WriteString("\n")
	if p.desc != "" {
		fmt.Fprintf(&b, "\n%s\n", p.desc)
	}

	w := tabwriter.NewWriter(&b, 0, 0, 2, ' ', 0)
	if len(p.args) > 0 || p.rest != nil {
		fmt.Fprintln(w, "\nArguments:")
		for _, a := range p.args {
			fmt.Fprintf(w, "  %s\t%s\n", a.name, a.usage)
		}
		if p.rest != nil {
			fmt.Fprintf(w, "  %s...\t%s\n", p.rest.name, p.rest.usage)
		}
		w.Flush()
	}

	fmt.Fprintln(w, "\nOptions:")
	for _, f := range p.flags {
		fmt.Fprintf(w, "  %s\t%s\n", flagLabel(f), flagUsage(f))
	}
	fmt.Fprintf(w, "  -h, --help\tshow this help\n")
	w.Flush()
	return b.String()
}

func flagLabel(f *flag) string {
	s := "    --" + f.name
	if f.short != "" {
		s = "-" + f.short + ", --" + f.name
	}
	if !f.isBool {
		s += " <value>"
	}
	return s
}

func flagUsage(f *flag) string {
	if f.def == "" {
		return f.usage
	}
	return fmt.Sprintf("%s (default %s)", f.usage, f.def)
}
